mapper.select:
select t1.*
from TBL_CEA_CANCEL_HOLIDAY t1
left join TBL_STAFF t2 on t2.STAFFID = t1.PEOPLE
where 1=1 and (t1.creator = #{param.creator}

   or t1.creator in (SELECT DISTINCT STAFFID FROM TBL_USER_ORGRELATION WHERE DEPTID IN (${param.getDeptIds}))
)

    and t2.REALNAME like concat('%',concat(#{param.peopleName},'%'))


    and t1.fillFormTime >= #{param.fillFormTimeStart}


    and t1.fillFormTime < #{param.fillFormTimeEnd}







order by t1.id desc
